#@title Resume Prediction { vertical-output: true }

# --- FORM INPUTS ---
#@markdown ### Personal Information
years_of_experience = 6 #@param {type:"number"}
skills_match_score = 84.7 #@param {type:'number'}
education_level = "Bachelors" #@param ["Bachelors", "Masters", "High School", "PhD"]
project_count = 7 #@param {type:'number'}
resume_length = 234 #@param {type:'number'}
github_activity = 158 #@param {type:'number'}

# Create a dictionary for the input
input_data = {
    'years_of_experience': years_of_experience, 'skills_match_score': skills_match_score,
    'education_level': education_level, 'project_count': project_count,
    'resume_length': resume_length, 'github_activity': github_activity
}

# Convert to DataFrame
input_df = pd.DataFrame([input_data])

# Define the expected order of columns based on the training data (X_train_smote)
expected_columns = ['years_of_experience', 'skills_match_score', 'education_level', 'project_count',
                    'resume_length', 'github_activity']

# Reindex the input_df to match the order of columns in the training data
input_df = input_df[expected_columns]

# Apply Label Encoding using the saved encoders
for col, encoder in encoders.items():
    if col in input_df.columns:
        # Handle cases where input might be new/unseen during training
        try:
            input_df[col] = encoder.transform(input_df[col])
        except ValueError:
            # If a new category is encountered, use the first class known by the encoder
            # This is a fallback and might need more sophisticated handling in a production setting
            input_df[col] = encoder.transform([encoder.classes_[0]])[0]

# Make Prediction
prediction = model.predict(input_df)
probability = model.predict_proba(input_df)[0][1]

# Display Results
print("-" * 30)
if prediction[0] == 1:
    print(f"RESULT: Shortlisted")
    print(f"CONFIDENCE: {probability:.2%}")
else:
    print(f"RESULT: Not shortlisted")
    print(f"CONFIDENCE: {(1-probability):.2%}")
